def git_meta(root):
    meta={"root":None,"head":None,"branch":None,"remote":None,"dirty":None}
    try:
        p=subprocess.run(
            ["git","-C",str(root),"rev-parse","--show-toplevel"],
            text=True,capture_output=True,timeout=20
        )
        if p.returncode!=0:
