            rel=gr.relative_to(wd).as_posix()
        except Exception:
            return meta
        meta["root"]="." if rel=="." else rel
        def run(args):
            q=subprocess.run(
                ["git","-C",str(gr),*args],
                text=True,capture_output=True,timeout=20
            )
            return q.stdout.strip() if q.returncode==0 else None
        meta["head"]=run(["rev-parse","HEAD"])
        meta["branch"]=run(["branch","--show-current"])
        meta["remote"]=run(["remote","get-url","origin"])
