executor_result=tmp/"EXECUTOR_RESULT.json"
validation_path=tmp/"VALIDATION.json"
review_path=tmp/"REVIEW.json"
baseline_path=tmp/"EXECUTION_BASELINE.json"

def emit(ok,reason,context=None):
    obj={"decision":"allow" if ok else "deny","reason":reason}
    if context:
        obj["additionalContext"]=context
    print(json.dumps(obj))
    raise SystemExit(0)

def load(path):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}

def file_sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def safe_path(value):
    if not isinstance(value,str) or not value or value==".":
        return False
    if value.startswith("/") or "\\" in value:
        return False
    pure=pathlib.PurePosixPath(value)
    if ".." in pure.parts:
        return False
    if any(ch in value for ch in "*?[]"):
        return False
    return True

def path_match(entry,path):
    return (entry.endswith("/") and path.startswith(entry)) or path==entry

def node_fingerprint(node):
    core={
        "id":node.get("id"),
        "goal":node.get("goal"),
        "depends_on":node.get("depends_on")
    }
    raw=json.dumps(core,sort_keys=True,separators=(",",":")).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()

def validate_commands(commands,label):
    if not isinstance(commands,list) or not (1<=len(commands)<=20):
        raise ValueError(label+" must contain 1..20 commands")
    for n,cmd in enumerate(commands,1):
        if not isinstance(cmd,dict):
            raise ValueError(label+" command "+str(n)+" must be an object")
        argv=cmd.get("argv")
        exp=cmd.get("expected_exit_code")
        timeout=cmd.get("timeout_seconds")
        if not isinstance(argv,list) or not (1<=len(argv)<=64):
            raise ValueError(label+" argv invalid")
        if not all(isinstance(x,str) and x for x in argv):
            raise ValueError(label+" argv entries must be non-empty strings")
        if not isinstance(exp,int):
            raise ValueError(label+" expected_exit_code must be integer")
        if not isinstance(timeout,int) or not (1<=timeout<=1800):
            raise ValueError(label+" timeout_seconds must be 1..1800")

def validate_bundle(intake,state):
    if not contract_path.is_file() or not graph_path.is_file() or not item_path.is_file():
        raise ValueError("CONTRACT.json, WORK_GRAPH.json and CURRENT_WORK_ITEM.json are required")

    contract=load(contract_path)
    graph=load(graph_path)
    work=load(item_path)

    if contract.get("schema_version")!=1:
        raise ValueError("CONTRACT schema_version must be 1")
    if contract.get("request_sha256")!=intake.get("request_sha256"):
        raise ValueError("CONTRACT request_sha256 does not match INTAKE")
    if not isinstance(contract.get("objective"),str) or not contract["objective"].strip():
        raise ValueError("CONTRACT objective must be non-empty")
    acc=contract.get("acceptance_criteria")
    if not isinstance(acc,list) or not acc or not all(isinstance(x,str) and x.strip() for x in acc):
        raise ValueError("CONTRACT acceptance_criteria must be a non-empty string list")
    constraints=contract.get("constraints")
    if not isinstance(constraints,list) or not all(isinstance(x,str) and x.strip() for x in constraints):
        raise ValueError("CONTRACT constraints must be a string list")
    global_forbidden=contract.get("global_forbidden_paths")
    if not isinstance(global_forbidden,list) or not global_forbidden:
        raise ValueError("CONTRACT global_forbidden_paths must be non-empty")
    if not all(safe_path(x) for x in global_forbidden):
        raise ValueError("CONTRACT global_forbidden_paths contains unsafe path")
    if ".agents_tmp/" not in global_forbidden or ".git/" not in global_forbidden:
        raise ValueError("CONTRACT must forbid .agents_tmp/ and .git/")
    validate_commands(contract.get("final_validation_commands"),"CONTRACT final_validation_commands")

    if graph.get("schema_version")!=1:
        raise ValueError("WORK_GRAPH schema_version must be 1")
    nodes=graph.get("nodes")
    if not isinstance(nodes,list) or not (1<=len(nodes)<=64):
        raise ValueError("WORK_GRAPH nodes must contain 1..64 nodes")
    byid={}
    for node in nodes:
        if not isinstance(node,dict):
            raise ValueError("WORK_GRAPH node must be an object")
        if set(node.keys())!={"id","goal","depends_on"}:
            raise ValueError("WORK_GRAPH nodes may contain only id, goal, depends_on")
        nid=node.get("id")
        goal=node.get("goal")
        deps=node.get("depends_on")
        if not isinstance(nid,str) or not re.fullmatch(r"[A-Za-z0-9_.-]{1,80}",nid):
            raise ValueError("WORK_GRAPH node id is invalid")
        if nid in byid:
            raise ValueError("WORK_GRAPH duplicate node id")
        if not isinstance(goal,str) or not goal.strip():
            raise ValueError("WORK_GRAPH node goal must be non-empty")
        if not isinstance(deps,list) or not all(isinstance(x,str) for x in deps):
            raise ValueError("WORK_GRAPH depends_on must be a string list")
        if len(deps)!=len(set(deps)):
            raise ValueError("WORK_GRAPH depends_on must not contain duplicates")
        byid[nid]=node

    for node in nodes:
        for dep in node["depends_on"]:
            if dep not in byid:
                raise ValueError("WORK_GRAPH dependency is missing")
            if dep==node["id"]:
                raise ValueError("WORK_GRAPH self dependency")

    visiting=set()
    done=set()
    def visit(nid):
        if nid in done:
            return
        if nid in visiting:
            raise ValueError("WORK_GRAPH must be acyclic")
        visiting.add(nid)
        for dep in byid[nid]["depends_on"]:
            visit(dep)
        visiting.remove(nid)
        done.add(nid)
    for nid in byid:
        visit(nid)

    completed=state.get("completed_nodes")
    if not isinstance(completed,dict):
        raise ValueError("STATE completed_nodes invalid")
    for nid,fingerprint in completed.items():
        if nid not in byid:
            raise ValueError("WORK_GRAPH removed a completed node")
        if node_fingerprint(byid[nid])!=fingerprint:
            raise ValueError("WORK_GRAPH mutated a completed node")

    current=graph.get("current_node_id")
    if not isinstance(current,str) or current not in byid:
        raise ValueError("WORK_GRAPH current_node_id must select an existing node")
    if current in completed:
        raise ValueError("WORK_GRAPH current node is already completed")
    for dep in byid[current]["depends_on"]:
        if dep not in completed:
            raise ValueError("WORK_GRAPH current node has incomplete dependencies")

    if work.get("schema_version")!=1:
        raise ValueError("CURRENT_WORK_ITEM schema_version must be 1")
    if work.get("node_id")!=current:
        raise ValueError("CURRENT_WORK_ITEM node_id must match WORK_GRAPH current_node_id")
    if not isinstance(work.get("goal"),str) or not work["goal"].strip():
        raise ValueError("CURRENT_WORK_ITEM goal must be non-empty")
    reuse=work.get("reuse_analysis")
    if not isinstance(reuse,str) or not reuse.strip():
        raise ValueError("CURRENT_WORK_ITEM reuse_analysis must be non-empty")
    mutable=work.get("mutable_paths")
    forbidden=work.get("forbidden_paths")
    if not isinstance(mutable,list) or not mutable or not all(safe_path(x) for x in mutable):
        raise ValueError("CURRENT_WORK_ITEM mutable_paths must be non-empty safe literal paths")
    if not isinstance(forbidden,list) or not forbidden or not all(safe_path(x) for x in forbidden):
        raise ValueError("CURRENT_WORK_ITEM forbidden_paths must be non-empty safe literal paths")
    for entry in global_forbidden:
        if entry not in forbidden:
            raise ValueError("CURRENT_WORK_ITEM must inherit all global forbidden paths")
    for m in mutable:
        if any(path_match(f,m) for f in forbidden):
            raise ValueError("CURRENT_WORK_ITEM mutable path is inside forbidden scope")
    wacc=work.get("acceptance_criteria")
    if not isinstance(wacc,list) or not wacc or not all(isinstance(x,str) and x.strip() for x in wacc):
        raise ValueError("CURRENT_WORK_ITEM acceptance_criteria must be a non-empty string list")
    validate_commands(work.get("validation_commands"),"CURRENT_WORK_ITEM validation_commands")

    return contract,graph,work,byid

if terminal.is_file():
    emit(False,"Bibliotecario is terminally failed; stop and report TERMINAL_FAILURE.json")
if resume not in (None,""):
    emit(False,"Fresh Bibliotecario phase calls require resume omitted/null/empty")
if a not in {"planner-qwen","executor-spark","reviewer-qwen"}:
