state=load(state_path)
intake=load(intake_path)
if state.get("schema_version")!=2:
    emit(False,"STATE.json missing or invalid")
if intake.get("schema_version")!=2 or (intake.get("source") or {}).get("kind")=="unknown":
    emit(False,"valid deterministic INTAKE.json is required")

source_root_raw=((intake.get("source") or {}).get("source_root") or ".")
source_root=(wd/source_root_raw).resolve()
try:
