            "phase":"planner",
            "reason":"planner call budget exceeded",
            "generated_at_utc":datetime.now(timezone.utc).isoformat()
        },indent=2)+"\n",encoding="utf-8")
        emit(False,"planner call budget exceeded; workflow terminally failed")
    state["planner_calls"]=n
    state_path.write_text(json.dumps(state,indent=2)+"\n",encoding="utf-8")
    try:
        planner_result.unlink()
    except FileNotFoundError:
        pass
    emit(True,"planner-qwen delegation allowed")

if a=="executor-spark":
    root=pathlib.Path(os.environ.get("OH_PERSISTENCE_DIR") or (pathlib.Path.home()/".openhands"))
    if not (root/"profiles"/"spark2.5-4b.json").is_file():
        emit(False,"executor-spark requires runtime profile spark2.5-4b")

    pr=load(planner_result)
    if pr.get("verdict")!="READY":
        emit(False,"executor-spark requires mechanically recorded PLANNING_RESULT: READY")

    try:
        contract,graph,work,byid=validate_bundle(intake,state)
    except Exception as ex:
        planner_result.write_text(json.dumps({
            "verdict":"INVALID_CONTRACT",
            "reason":str(ex),
            "generated_at_utc":datetime.now(timezone.utc).isoformat()
        },indent=2)+"\n",encoding="utf-8")
        emit(
            False,
            "WORK_CONTRACT_INVALID before executor: "+str(ex),
            "Call planner-qwen again. Spark must not start until the JSON contract bundle validates."
        )

    contract_sha=file_sha(contract_path)
    locked=state.get("contract_sha256")
    if locked is None:
        state["contract_sha256"]=contract_sha
    elif locked!=contract_sha:
        terminal.write_text(json.dumps({
            "phase":"contract",
            "reason":"locked CONTRACT.json changed",
            "expected_sha256":locked,
            "actual_sha256":contract_sha,
            "generated_at_utc":datetime.now(timezone.utc).isoformat()
        },indent=2)+"\n",encoding="utf-8")
        emit(False,"locked CONTRACT.json changed; workflow terminally failed")

    graph_sha=file_sha(graph_path)
    work_sha=file_sha(item_path)
    attempts=state.get("executor_attempts")
    if not isinstance(attempts,dict):
        attempts={}
    prior_attempts=int(attempts.get(work_sha,0))
    if prior_attempts>0:
        val=load(validation_path)
        if not (val.get("overall")=="FAIL" and val.get("phase")=="WORK_ITEM"):
            emit(False,"same work item may be retried only after deterministic WORK_ITEM validation FAIL")
    if prior_attempts>=4:
        terminal.write_text(json.dumps({
            "phase":"executor",
            "reason":"work-item executor attempt budget exceeded",
            "work_item_sha256":work_sha,
            "generated_at_utc":datetime.now(timezone.utc).isoformat()
        },indent=2)+"\n",encoding="utf-8")
        emit(False,"executor work-item budget exceeded; workflow terminally failed")

    baseline=load(baseline_path)
    if baseline.get("work_item_sha256")!=work_sha:
        entries={}
        probe=subprocess.run(
            ["git","-C",str(source_root),"rev-parse","--show-toplevel"],
            text=True,capture_output=True,timeout=30
        )
        git_root=None
        git_rel=None
        if probe.returncode==0:
            gr=pathlib.Path(probe.stdout.strip()).resolve()
            try:
                rr=gr.relative_to(wd).as_posix()
                git_root=gr
                git_rel="." if rr=="." else rr
            except Exception:
                git_root=None
        if git_root is None:
            emit(False,"executor baseline requires Git-backed workspace")

        st=subprocess.run(
            ["git","-C",str(git_root),"status","--porcelain=v1","--untracked-files=all"],
            text=True,capture_output=True,timeout=120
        )
        if st.returncode!=0:
            emit(False,"executor baseline git status failed")
        for line in st.stdout.splitlines():
            if len(line)<4:
                continue
            code=line[:2]
            pt=line[3:]
            if " -> " in pt:
                pt=pt.split(" -> ",1)[1]
            p=(git_root/pathlib.PurePosixPath(pt)).resolve()
            try:
                rel=p.relative_to(wd).as_posix()
            except Exception:
                continue
            if rel.startswith(".agents_tmp/"):
                continue
            digest=None
            size=None
            if p.is_file():
                h=hashlib.sha256()
                try:
                    with p.open("rb") as fh:
                        for chunk in iter(lambda:fh.read(1024*1024),b""):
                            h.update(chunk)
                    digest=h.hexdigest()
                    size=p.stat().st_size
                except OSError:
                    pass
            entries[rel]={"status":code,"sha256":digest,"size":size}

        baseline={
            "schema_version":3,
            "generated_at_utc":datetime.now(timezone.utc).isoformat(),
            "source_root":source_root_raw,
            "git_root":git_rel,
            "contract_sha256":contract_sha,
            "graph_sha256":graph_sha,
            "work_item_sha256":work_sha,
            "node_id":work["node_id"],
            "entries":entries
        }
        baseline_path.write_text(
            json.dumps(baseline,indent=2,sort_keys=True)+"\n",
            encoding="utf-8"
        )

    attempts[work_sha]=prior_attempts+1
    state["executor_attempts"]=attempts
    state["executor_calls"]=int(state.get("executor_calls",0))+1
    if state["executor_calls"]>128:
